def search_algorithm(src, dsts, G, num_partitions):
    """Build a shared-cost broadcast tree, exactly for small receiver sets."""
    import heapq

    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    h.remove_edges_from([
        (u, v) for u, v, data in h.edges(data=True)
        if data.get("cost") is None
    ])

    terminals = [dst for dst in dict.fromkeys(dsts) if dst != src]
    topology = BroadCastTopology(src, dsts, num_partitions)
    if not terminals:
        return topology

    for dst in terminals:
        if not nx.has_path(h, src, dst):
            raise nx.NetworkXNoPath(
                "No priced broadcast route from %s to %s" % (src, dst)
            )

    def emit(routes):
        """Write each root-to-destination tree path to every partition."""
        for dst in dsts:
            if dst == src:
                continue
            for u, v in zip(routes[dst], routes[dst][1:]):
                for partition in range(num_partitions):
                    topology.append_dst_partition_path(
                        dst, partition, [u, v, G[u][v]]
                    )
        return topology

    # Directed Steiner DP: a subtree for two terminal subsets can merge at a
    # relay, then its common upstream edge is paid only once.
    if len(terminals) <= 8:
        nodes = list(h)
        incoming = {
            node: [(parent, float(h[parent][node]["cost"]))
                   for parent in h.predecessors(node)]
            for node in nodes
        }
        dp, choices = {}, {}

        for mask in range(1, 1 << len(terminals)):
            costs = {node: float("inf") for node in nodes}
            decisions, queue, serial = {}, [], 0

            if mask & (mask - 1) == 0:
                terminal = terminals[mask.bit_length() - 1]
                costs[terminal] = 0.0
                decisions[terminal] = ("terminal",)
                heapq.heappush(queue, (0.0, serial, terminal))
                serial += 1
            else:
                subset = (mask - 1) & mask
                while subset:
                    other = mask ^ subset
                    if other and subset < other:
                        for node in nodes:
                            value = dp[subset][node] + dp[other][node]
                            if value < costs[node]:
                                costs[node] = value
                                decisions[node] = ("merge", subset, other)
                    subset = (subset - 1) & mask

                for node in nodes:
                    if costs[node] < float("inf"):
                        heapq.heappush(queue, (costs[node], serial, node))
                        serial += 1

            while queue:
                value, _, node = heapq.heappop(queue)
                if value != costs[node]:
                    continue
                for parent, edge_cost in incoming[node]:
                    candidate = value + edge_cost
                    if candidate + 1e-12 < costs[parent]:
                        costs[parent] = candidate
                        decisions[parent] = ("step", node)
                        heapq.heappush(queue, (candidate, serial, parent))
                        serial += 1

            dp[mask], choices[mask] = costs, decisions

        edges = set()

        def collect(mask, node):
            action = choices[mask][node]
            if action[0] == "step":
                edges.add((node, action[1]))
                collect(mask, action[1])
            elif action[0] == "merge":
                collect(action[1], node)
                collect(action[2], node)

        collect((1 << len(terminals)) - 1, src)
        tree = nx.DiGraph()
        tree.add_edges_from(edges)
        return emit({
            dst: nx.shortest_path(tree, src, dst)
            for dst in terminals
        })

    # Large fan-outs use several greedy insertion orders.  Edges already in
    # the tree are free during insertion, so subsequent destinations naturally
    # attach to existing relays rather than duplicate expensive cloud egress.
    def build(order):
        routes, used = {}, set()
        for dst in order:
            path = nx.shortest_path(
                h, src, dst,
                weight=lambda u, v, data:
                    0.0 if (u, v) in used else float(data["cost"])
            )
            routes[dst] = path
            used.update(zip(path, path[1:]))
        return routes

    def tree_cost(routes):
        return sum(
            float(h[u][v]["cost"])
            for u, v in {
                edge
                for path in routes.values()
                for edge in zip(path, path[1:])
            }
        )

    distances = nx.single_source_dijkstra_path_length(h, src, weight="cost")
    near_first = sorted(terminals, key=lambda node: (distances[node], str(node)))
    orders = []
    for sequence in (terminals, list(reversed(terminals)),
                     near_first, list(reversed(near_first))):
        for index in range(len(sequence)):
            orders.append(sequence[index:] + sequence[:index])

    return emit(min((build(order) for order in orders), key=tree_cost))
